selector_to_html = {"a[href=\"requirements.html#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8f6f\u4ef6\u8981\u6c42<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u53ef\u9009\u6269\u5c55\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">pyproject.toml</span></code> \u4e2d\u58f0\u660e\uff0c\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span> <span class=\"pre\">install</span> <span class=\"pre\">\"flagquantum[&lt;extra&gt;]\"</span></code> \u5b89\u88c5\uff1a</p>", "a[href=\"install.html#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5\u6b63\u5f0f\u53d1\u5e03\u7684\u5305<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2>", "a[href=\"requirements.html#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u786c\u4ef6\u5e73\u53f0<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>FlagQuantum \u4e0d\u505a\u5382\u5546\u63a2\u6d4b\uff0c\u4e5f\u4e0d\u542b\u5382\u5546\u5206\u652f\u3002\u7269\u7406\u8bbe\u5907\u63a2\u6d4b\u3001\u5382\u5546\u8fd0\u884c\u65f6\u4ee5\u53ca\n<code class=\"docutils literal notranslate\"><span class=\"pre\">flagos:0</span></code> \u5230\u7269\u7406\u5361\u7684\u6620\u5c04\uff0c\u90fd\u5c5e\u4e8e FlagOS \u5382\u5546\u96c6\u6210\uff1bFlagQuantum \u53ea\u8bb0\u5f55\u5b83\u62ff\u5230\n\u7684\u8fd0\u884c\u65f6\u6807\u8bc6\u4e0e\u8def\u7531\u8bc1\u636e\u3002\u56e0\u6b64\uff0c\u4ec5\u5b58\u5728\u4e00\u6761\u96c6\u6210\u8def\u5f84\u5e76\u4e0d\u7b49\u4e8e\u67d0\u6b3e\u56fd\u4ea7\u52a0\u901f\u5668\u5df2\u83b7\u5f97\u8ba4\u8bc1\u3002</p>", "a[href=\"install.html#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5\u5f00\u53d1\u7248\u672c<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"install.html#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9a8c\u8bc1\u5b89\u88c5<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u5305\u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">flagquantum</span> <span class=\"pre\">as</span> <span class=\"pre\">fq</span></code> \u5f15\u5165\uff1b\u5bfc\u5165\u5b83\u4e0d\u4f1a\u5bfc\u5165\u53ef\u9009\u4f9d\u8d56\u3001\u4e0d\u4f1a\u53d1\u73b0\u6269\u5c55\uff0c\n\u4e5f\u4e0d\u4f1a\u6fc0\u6d3b\u5382\u5546\u9002\u914d\u5668\u3002</p>", "a[href=\"install.html#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u53ef\u9009\u4f9d\u8d56\u7ec4<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u53ea\u5728\u9700\u8981\u65f6\u5b89\u88c5\u5bf9\u5e94\u80fd\u529b\uff1a</p>", "a[href=\"quick-start.html#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8ba9\u540c\u4e00\u4e2a\u6a21\u578b\u6362\u4e00\u79cd\u8868\u793a\u8fd0\u884c<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/quick_start.py</span></code> \u8bad\u7ec3\u4e00\u4e2a\u89e3\u5df2\u77e5\u7684\u7ecf\u5178\u2014\u91cf\u5b50\u6df7\u5408\u6a21\u578b\uff0c\u5e76\u53ef\u5728\u547d\u4ee4\u884c\u5207\u6362\u6a21\u62df\u8868\u793a\uff1a</p>", "a[href=\"quick-start.html#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8bad\u7ec3\u7b2c\u4e00\u4e2a\u91cf\u5b50\u6a21\u578b<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u6784\u5efa\u4e00\u4e2a\u53cc\u91cf\u5b50\u6bd4\u7279\u7ebf\u8def\uff0c\u5e76\u901a\u8fc7\u6700\u5c0f\u5316 0 \u53f7\u7ebf\u4e0a\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">Z</span></code> \u671f\u671b\u503c\u6765\u5b66\u4e60\u5b83\u7684\u65cb\u8f6c\u89d2\uff1a</p>", "a[href=\"requirements.html#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u591a\u673a\u73af\u5883\u9884\u671f<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u5206\u5e03\u5f0f\u652f\u6301\u4f9d\u8d56\u5177\u4f53\u73af\u5883\u3002\u5728\u5df2\u590d\u6838\u7684\u914d\u7f6e\u4e2d\uff0c\u53cc\u673a A800\u3001\u6bcf\u673a\u4e00\u5f20\u5361\u7684\u90e8\u7f72\u53ef\u4ee5\u57fa\u4e8e\nNCCL \u4e0e TCP \u8fd0\u884c\u524d\u5411\u3001\u68af\u5ea6\u4e0e\u8bad\u7ec3\uff0f\u6062\u590d\u8d1f\u8f7d\uff1b\u591a\u673a\u7684\u53d1\u5e03\u8ba4\u8bc1\u662f\u53e6\u4e00\u4e2a\u9700\u8981\u8bc1\u636e\u652f\u6491\u7684\n\u72ec\u7acb\u6b65\u9aa4\u3002</p>", "a[href=\"quick-start.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u672c\u9875\u8bad\u7ec3\u4e00\u4e2a\u53cc\u91cf\u5b50\u6bd4\u7279\u6a21\u578b\uff0c\u7136\u540e\u6f14\u793a\u5982\u4f55\u5728\u4e0d\u6539\u52a8\u6a21\u578b\u7684\u60c5\u51b5\u4e0b\u5207\u6362\u6a21\u62df\u8868\u793a\u3002</p>", "a[href=\"install.html#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8fd0\u884c\u4e00\u4e2a\u672c\u5730\u793a\u4f8b<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u53d7\u7ef4\u62a4\u7684\u672c\u5730\u8def\u5f84\u4e0d\u9700\u8981\u51ed\u636e\u3001\u4e0d\u9700\u8981\u8fdc\u7a0b\u8d44\u6e90\uff0c\u4e5f\u4e0d\u9700\u8981\u53ef\u9009\u540e\u7aef\uff1a</p>", "a[href=\"quick-start.html#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6267\u884c\u524d\u5148\u67e5\u770b\u7ebf\u8def\u4e0e\u8ba1\u5212<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u8ba1\u5212\u53ef\u4ee5\u5e8f\u5217\u5316\u4e0e\u6062\u590d\u3002\u628a\u6062\u590d\u540e\u7684\u8ba1\u5212\u4ea4\u7ed9 <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code> \u4f1a\u7cbe\u786e\u6267\u884c\u8be5\u8ba1\u5212\uff1a\u4e0d\u4f1a\u91cd\u65b0\u89c4\u5212\uff0c\n\u4e5f\u4e0d\u4f1a\u88ab\u9759\u9ed8\u66ff\u6362\u6210\u53e6\u4e00\u4e2a\u540e\u7aef\u3002</p>", "a[href=\"quick-start.html#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0b\u4e00\u6b65<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u73af\u5883\u8981\u6c42<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum \u652f\u6301 Python 3.10 \u81f3 3.12\uff0c\u5e76\u8981\u6c42 PyTorch 2.5 \u6216\u66f4\u9ad8\u7248\u672c\u3002\u6b63\u5f0f\u53d1\u5e03\u7684\n\u5305\u53ea\u4f9d\u8d56 PyTorch\uff0c\u5176\u4f59\u80fd\u529b\u90fd\u662f\u53ef\u9009\u6269\u5c55\u3002</p>", "a[href=\"#flagquantum\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagQuantum \u5feb\u901f\u5165\u95e8<a class=\"headerlink\" href=\"#flagquantum\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd FlagQuantum \u7684\u5b89\u88c5\u8981\u6c42\u3001\u5b89\u88c5\u8fc7\u7a0b\uff0c\u4ee5\u53ca\u7b2c\u4e00\u4e2a\u53ef\u8bad\u7ec3\u7684\u91cf\u5b50\u6a21\u578b\u3002</p>", "a[href=\"install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5 FlagQuantum<a class=\"headerlink\" href=\"#flagquantum\" title=\"Link to this heading\">#</a></h1><p>\u5f00\u59cb\u524d\u8bf7\u5148\u9605\u8bfb<a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">\u73af\u5883\u8981\u6c42</span></a>\u3002</p>", "a[href=\"install.html#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0b\u4e00\u6b65<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><p>\u7ee7\u7eed\u9605\u8bfb<a class=\"reference internal\" href=\"quick-start.html\"><span class=\"std std-doc\">\u5feb\u901f\u5f00\u59cb</span></a>\uff0c\u6216\u76f4\u63a5\u67e5\u770b<a class=\"reference internal\" href=\"#../user_guide/simulation-modes.md\"><span class=\"xref myst\">\u6a21\u62df\u6a21\u5f0f</span></a>\n\u4ee5\u9009\u62e9\u8868\u793a\u5f62\u5f0f\uff0c\u4ee5\u53ca<a class=\"reference internal\" href=\"#../user_guide/remote-execution.md\"><span class=\"xref myst\">\u8fdc\u7a0b\u6267\u884c</span></a>\u4e86\u89e3\u5382\u5546\u76ee\u6807\u3002</p>"}
